import { test, expect } from '@playwright/test';

test.describe('File Upload - Invalid File Type Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should display error message when uploading an unsupported file type', async ({ page }) => {
    // Locate and click the file input using getByLabel
    const fileInput = page.getByLabel('Upload File');
    await fileInput.click();

    // Set up the file input with an unsupported file (e.g., .exe)
    const fileChooser = await page.waitForFileChooser();
    await fileChooser.setFiles('fixtures/unsupported.exe');

    // Locate and click the upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Wait for the error message to appear
    const errorMessage = page.getByText(/unsupported file type/i);
    await expect(errorMessage).toBeVisible();

    // Verify the error message contains specific details
    await expect(errorMessage).toContainText('Only PDF and DOCX files are allowed');

    // Verify the upload button is still enabled for retry
    await expect(uploadButton).toBeEnabled();
  });

  test('should allow upload of supported file type and clear error message', async ({ page }) => {
    // Locate and click the file input using getByLabel
    const fileInput = page.getByLabel('Upload File');
    await fileInput.click();

    // Set up the file input with a supported file (e.g., .pdf)
    const fileChooser = await page.waitForFileChooser();
    await fileChooser.setFiles('fixtures/document.pdf');

    // Locate and click the upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Wait for success message
    const successMessage = page.getByText(/file uploaded successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify the error message does not exist
    const errorMessage = page.getByText(/unsupported file type/i);
    await expect(errorMessage).not.toBeVisible();

    // Verify the file name is displayed
    const fileNameDisplay = page.getByText('document.pdf');
    await expect(fileNameDisplay).toBeVisible();
  });
});
